package cn.breezeth.kaleidoscope_grilling;
import net.minecraft.world.effect.MobEffectInstance; import net.minecraft.world.effect.MobEffects; import net.minecraft.world.entity.LivingEntity; import net.minecraft.world.item.ItemStack; import net.minecraft.world.level.Level; import java.util.List;
public final class FoodState {private static final String HOT_UNTIL="HotUntil";public static void setHot(ItemStack s,long until){s.getOrCreateTag().putLong(HOT_UNTIL,until);}public static boolean isHot(ItemStack s,Level l){return s.hasTag()&&s.getTag().getLong(HOT_UNTIL)>l.getGameTime();}public static void applySeasoning(ItemStack s,Level l,LivingEntity e){if(!isHot(s,l))return;List<String> values=SeasoningData.get(s);int duration=3600;long hout=values.stream().filter("kaleidoscope_grilling:houttuynia_powder"::equals).count();if(hout>=4)duration*=4;else if(hout>0)duration*=2;long red=values.stream().filter("minecraft:redstone"::equals).count();long gun=values.stream().filter("minecraft:gunpowder"::equals).count();if(red>0)e.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED,duration,red>=4?1:0));if(gun>0)e.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST,duration,gun>=4?1:0));AdvancedSeasoningHandler.apply(e,values,duration);}private FoodState(){}}
